return $input.all().map(({json}, index) => {
  const {trades} = json;
  if (!Array.isArray(trades)) throw new Error("Expected a backtest trade list");
  let cumulativeR = 0, peakR = 0, maxClosedTradeDrawdownR = 0;
  let plannedR = 0, gainsR = 0, lossesR = 0, wins = 0, losses = 0;
  const completed = trades.map(trade => {
    const {direction, entry, stop, target, exit, roundTripCost, closedAt} = trade;
    if (!["BUY", "SELL"].includes(direction) ||
        ![entry, stop, target, exit].every(v => Number.isFinite(v) && v > 0) ||
        !Number.isFinite(roundTripCost) || roundTripCost < 0 ||
        typeof closedAt !== "string" || !closedAt.endsWith("Z") || !Number.isFinite(Date.parse(closedAt))) {
      throw new Error("Invalid simulated trade or missing round-trip cost");
    }
    const sign = direction === "BUY" ? 1 : -1;
    const risk = (entry - stop) * sign;
    const reward = (target - entry) * sign;
    if (risk <= 0 || reward <= 0) throw new Error("Stop and target must bracket entry in trade direction");
    return {closedAt: Date.parse(closedAt), plannedR: reward / risk, netR: ((exit - entry) * sign - roundTripCost) / risk};
  }).sort((left, right) => left.closedAt - right.closedAt);
  // Settle trades sharing a timestamp together so input order cannot alter drawdown.
  let settlement = 0;
  for (const [i, trade] of completed.entries()) {
    plannedR += trade.plannedR;
    settlement += trade.netR;
    if (trade.netR > 0) { gainsR += trade.netR; wins++; }
    if (trade.netR < 0) { lossesR -= trade.netR; losses++; }
    if (completed[i + 1]?.closedAt !== trade.closedAt) {
      cumulativeR += settlement;
      peakR = Math.max(peakR, cumulativeR);
      maxClosedTradeDrawdownR = Math.max(maxClosedTradeDrawdownR, peakR - cumulativeR);
      settlement = 0;
    }
  }
  const count = completed.length;
  return {json:{count,wins,losses,breakeven:count-wins-losses,winRate:count?wins/count:null,
    avgPlannedRR:count?plannedR/count:null, netR:cumulativeR, expectancyR:count?cumulativeR/count:null,
    profitFactor:lossesR?gainsR/lossesR:null,maxClosedTradeDrawdownR},pairedItem:{item:index}};
});
